themes.css:
#wemd {
  --life-primary: #b8563f;
  --life-deep: #6e3529;
  --life-ink: #3f342e;
  --life-muted: #7d6c62;
  --life-paper: #fffaf1;
  --life-soft: #f7ead7;
  --life-line: #dfc9ae;
  color: var(--life-ink);
  font-family: Optima-Regular, Optima, 'PingFang SC', 'Microsoft YaHei', sans-serif;
  font-size: 16px;
  line-height: 1.85;
  letter-spacing: 0.02em;
  background: var(--life-paper);
  padding: 24px 22px;
}
#wemd p { margin: 1.15em 0; color: var(--life-ink); text-align: justify; }
#wemd h1 { margin: 1.5em 0 1.1em; color: var(--life-deep); font-size: 27px; line-height: 1.35; text-align: center; font-weight: 700; letter-spacing: 0.08em; }
#wemd h1::after { content: '◆  ◆  ◆'; display: block; margin-top: 13px; color: #d99b73; font-size: 8px; letter-spacing: 0.65em; }
#wemd h2 { margin: 2em 0 1em; padding: 8px 14px; color: #fffaf1; font-size: 21px; line-height: 1.45; background: var(--life-primary); border-radius: 3px 14px 14px 3px; box-shadow: 4px 4px 0 #ecd4bc; }
#wemd h3 { margin: 1.75em 0 0.8em; padding-left: 11px; color: var(--life-deep); font-size: 18px; line-height: 1.5; border-left: 4px solid #d99b73; }
#wemd h4 { margin: 1.5em 0 0.7em; color: var(--life-primary); font-size: 16px; }
#wemd strong { color: var(--life-deep); font-weight: 700; background: linear-gradient(transparent 68%, #f1d3a9 0); }
#wemd em { color: #8b5b47; }
#wemd a { color: var(--life-primary); text-decoration: none; border-bottom: 1px dashed #cf8068; }
#wemd blockquote { margin: 1.5em 0; padding: 16px 18px 16px 46px; color: #6c5144; background: #f8ead7; border: 1px solid #ead5ba; border-radius: 12px 4px 12px 4px; position: relative; }
#wemd blockquote::before { content: '“'; position: absolute; left: 14px; top: 2px; color: #d3916f; font-family: Georgia, serif; font-size: 46px; line-height: 1; }
#wemd blockquote p { margin: 0.35em 0; color: #6c5144; }
#wemd ul, #wemd ol { margin: 1em 0; padding-left: 1.7em; }
#wemd li { margin: 0.45em 0; padding-left: 0.25em; }
#wemd li::marker { color: var(--life-primary); font-weight: 700; }
#wemd hr { margin: 2.2em auto; width: 62%; height: 1px; border: 0; background: repeating-linear-gradient(90deg, #d6b998 0 7px, transparent 7px 13px); }
#wemd code { padding: 2px 6px; color: #8d3f31; background: #f4e5cf; border: 1px solid #e6cfb1; border-radius: 5px; font-family: Menlo, Consolas, monospace; font-size: 0.88em; }
#wemd pre { margin: 1.5em 0; padding: 17px 18px; overflow-x: auto; color: #f7ead7; background: #463a34; border-left: 5px solid #d98b61; border-radius: 5px 12px 12px 5px; box-shadow: 0 8px 22px rgba(86, 54, 37, 0.13); }
#wemd pre code { padding: 0; color: inherit; background: transparent; border: 0; }
#wemd img { display: block; max-width: 100%; margin: 1.7em auto 0.6em; border-radius: 12px 4px 12px 4px; box-shadow: 0 10px 26px rgba(95, 58, 38, 0.15); }
#wemd figcaption, #wemd .image-caption { color: var(--life-muted); font-size: 13px; text-align: center; }
#wemd table { width: 100%; margin: 1.5em 0; border-collapse: separate; border-spacing: 0; border: 1px solid var(--life-line); border-radius: 9px; overflow: hidden; font-size: 14px; }
#wemd th { padding: 10px; color: #fffaf1; background: var(--life-primary); border: 0; }
#wemd td { padding: 10px; background: #fffdf8; border: 0; border-bottom: 1px solid #eadbc8; }
#wemd tr:last-child td { border-bottom: 0; }
#wemd mark { padding: 0 3px; color: inherit; background: #f4d58f; }
#wemd .task-list-item { list-style: none; }
#wemd input[type='checkbox'] { accent-color: var(--life-primary); }

