#wemd img { display: block; max-width: 100%; margin: 1.7em auto 0.6em; padding: 5px; background: #fff; border: 1px solid #d7e5dc; border-radius: 6px; box-shadow: 0 8px 24px rgba(55, 99, 83, 0.11); }
